/** The original main.scene and Main.ts.meta keep their upstream UUID linkage. */
@ccclass('Main')
export class Main extends Root {
  private theatreScreenAdapterBound = false;
  private theatreScreenAdapterDisposed = false;
  private theatreResizeQueued = false;
  private theatreResolutionPolicy = -1;

  private bindTheatreScreenAdapter(): void {
    if (this.theatreScreenAdapterBound) return;
    this.theatreScreenAdapterBound = true;
    screen.on('window-resize', this.queueTheatreScreenAdapter, this);
    screen.on('fullscreen-change', this.queueTheatreScreenAdapter, this);
    screen.on('orientation-change', this.queueTheatreScreenAdapter, this);
    this.applyTheatreScreenAdapter();
  }

  private queueTheatreScreenAdapter(): void {
    if (this.theatreScreenAdapterDisposed || this.theatreResizeQueued) return;
    this.theatreResizeQueued = true;
    // Screen updates its physical size before emitting resize. Coalesce related
    // events until the engine has applied its view policy for this frame.
    this.scheduleOnce(this.flushTheatreScreenAdapter, 0);
  }

  private flushTheatreScreenAdapter(): void {
    this.theatreResizeQueued = false;
    if (!this.theatreScreenAdapterDisposed) this.applyTheatreScreenAdapter();
  }

  private applyTheatreScreenAdapter(): void {
    const physical = screen.windowSize;
    if (!(physical.width > 0 && physical.height > 0)
      || !Number.isFinite(physical.width) || !Number.isFinite(physical.height)) return;
    // Fixed baseline, never the previous Oops-expanded design resolution. The
    // policies scale uniformly and expose the remaining width/height to Canvas.
    const width = 390; const height = 844;
    const ratio = physical.width / physical.height;
    const policy = ratio > width / height ? ResolutionPolicy.FIXED_HEIGHT : ResolutionPolicy.FIXED_WIDTH;
    const targetWidth = policy === ResolutionPolicy.FIXED_HEIGHT ? height * ratio : width;
    const targetHeight = policy === ResolutionPolicy.FIXED_HEIGHT ? height : width / ratio;
    const design = view.getDesignResolutionSize(); const visible = view.getVisibleSize();
    if (this.theatreResolutionPolicy === policy && Math.abs(design.width - width) < 0.01
      && Math.abs(design.height - height) < 0.01 && Math.abs(visible.width - targetWidth) < 0.01
      && Math.abs(visible.height - targetHeight) < 0.01) return;
    this.theatreResolutionPolicy = policy;
    view.setDesignResolutionSize(width, height, policy);
  }

  onDestroy(): void {
    this.theatreScreenAdapterDisposed = true;
    this.theatreResizeQueued = false;
    this.unschedule(this.flushTheatreScreenAdapter);
    screen.off('window-resize', this.queueTheatreScreenAdapter, this);
    screen.off('fullscreen-change', this.queueTheatreScreenAdapter, this);
    screen.off('orientation-change', this.queueTheatreScreenAdapter, this);
    this.theatreScreenAdapterBound = false;
    super.onDestroy();
  }

  protected run(): void {
    // Root calls run only after config, default bundle and StorageManager are ready.
    if (!this.game || !this.gui || !oops.storage) throw new Error('Oops 剧院启动节点或运行服务未就绪');
    this.bindTheatreScreenAdapter();
    // The original game node is a Canvas sibling in upstream main.scene.
    // Keep that bound node, but move its 2D subtree beneath the actual Canvas.
    this.game.setParent(oops.gui.game);
    this.game.layer = Layers.Enum.UI_2D;
    const size = view.getVisibleSize();
    const gameTransform = this.game.getComponent(UITransform) ?? this.game.addComponent(UITransform);
    gameTransform.setContentSize(size.width, size.height);
    const gameWidget = this.game.getComponent(Widget) ?? this.game.addComponent(Widget);
    gameWidget.target = oops.gui.game;
    gameWidget.isAlignTop = gameWidget.isAlignBottom = gameWidget.isAlignLeft = gameWidget.isAlignRight = true;
    gameWidget.top = gameWidget.bottom = gameWidget.left = gameWidget.right = 0;
    gameWidget.alignMode = Widget.AlignMode.ALWAYS;
    gameWidget.updateAlignment();
    const stage = new Node('TheatreGameRuntime');
    stage.active = false;
    stage.layer = Layers.Enum.UI_2D;
    this.game.addChild(stage);
    stage.addComponent(UITransform).setContentSize(size.width, size.height);
    const widget = stage.addComponent(Widget);
    widget.target = this.game;
    widget.isAlignTop = widget.isAlignBottom = widget.isAlignLeft = widget.isAlignRight = true;
    widget.top = widget.bottom = widget.left = widget.right = 0;
    widget.alignMode = Widget.AlignMode.ALWAYS;
    const theatre = stage.addComponent(TheatreGame);
    if (FRAGRANCE_REMASTER) {
      theatre.layoutResource = 'fragrance-remaster/layout';
      theatre.resourcePrefix = 'fragrance-remaster';
      theatre.hitMetadataResource = 'fragrance-remaster/metadata/alpha-hit';
      theatre.motionProfile = 'fragrance-v3';
      stage.addComponent(MotionPerformanceProbe).target = theatre;
    } else if (SIMPLE_MOTION_TEST) {
      theatre.layoutResource = 'simple/simple-motion-layout';
      theatre.resourcePrefix = 'simple';
      theatre.hitMetadataResource = 'simple/metadata/alpha-hit';
      stage.addComponent(MotionPerformanceProbe).target = theatre;
    }
    theatre.configureRuntime(createOopsTheatreRuntime());
    stage.active = true;
    widget.updateAlignment();
  }
}
